package com.clavis.reader;
import android.content.*;import android.net.Uri;import android.os.ParcelFileDescriptor;import android.media.MediaMetadataRetriever;import java.io.*;import java.util.*;import org.json.*;
/** Automatic metadata-only discovery. Never recognizes speech or modifies audio files. */
final class ChapterDetection {
 static final class Discovery{final List<EmbeddedChapters.Marker> markers;final long duration;Discovery(List<EmbeddedChapters.Marker> m,long d){markers=m;duration=d;}}
 static boolean needs(Book b){return b.author.equals("Audio")&&b.chapterCount()==1&&!b.chaptersChecked;}
 static Discovery read(ContentResolver resolver,Book b)throws Exception{String uri=b.trackUri(0);List<EmbeddedChapters.Marker> raw;long duration=-1;if(uri.startsWith("file:")){try(FileInputStream in=new FileInputStream(new File(java.net.URI.create(uri)))){raw=EmbeddedChapters.read(in.getChannel());if(!raw.isEmpty()){MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(in.getFD());duration=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));}finally{m.release();}}}}else{try(ParcelFileDescriptor fd=resolver.openFileDescriptor(Uri.parse(uri),"r");FileInputStream in=new FileInputStream(fd.getFileDescriptor())){raw=EmbeddedChapters.read(in.getChannel());if(!raw.isEmpty()){MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(fd.getFileDescriptor());duration=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));}finally{m.release();}}}}
 TreeMap<Long,String> ordered=new TreeMap<>();for(EmbeddedChapters.Marker m:raw)if(m.time>=0&&m.time<duration)ordered.put(m.time,m.title);if(!raw.isEmpty()&&ordered.isEmpty())throw new IOException("Chapter duration unavailable");if(!ordered.isEmpty()&&ordered.firstKey()>2000)ordered.put(0L,"Opening");else if(!ordered.isEmpty()&&ordered.firstKey()>0){String title=ordered.remove(ordered.firstKey());ordered.put(0L,title);}ArrayList<EmbeddedChapters.Marker> result=new ArrayList<>();for(Map.Entry<Long,String> e:ordered.entrySet())result.add(new EmbeddedChapters.Marker(e.getKey(),e.getValue()));return new Discovery(result,duration);}
 static int index(List<EmbeddedChapters.Marker> markers,long position){int index=0;while(index+1<markers.size()&&markers.get(index+1).time<=position)index++;return index;}
 static void fill(Book b,Discovery found){b.chaptersChecked=true;if(found.markers.isEmpty())return;long absolute=b.trackStart(b.chapterIndex)+b.position;String uri=b.trackUri(0);b.chapters.clear();for(int i=0;i<found.markers.size();i++){EmbeddedChapters.Marker m=found.markers.get(i);b.chapters.add(new Book.Chapter(uri,m.title,m.time,i+1<found.markers.size()?found.markers.get(i+1).time:found.duration));}b.chapterIndex=index(found.markers,absolute);b.position=Math.max(0,absolute-b.trackStart(b.chapterIndex));b.duration=b.trackLength(b.chapterIndex,found.duration);}
 static void enrich(ContentResolver resolver,List<Book> books){for(Book b:books)if(needs(b))try{fill(b,read(resolver,b));}catch(Exception ignored){/* Retry on first playback if access or metadata was temporarily unavailable. */}}
 static void remap(Context c,Book old,Discovery found){if(found.markers.isEmpty())return;String key="bookmarks:"+old.uri;try{JSONArray marks=new JSONArray(c.getSharedPreferences("bookmarks",0).getString(key,"[]"));for(int i=0;i<marks.length();i++){JSONObject mark=marks.getJSONObject(i);int chapter=Math.max(0,Math.min(old.chapterCount()-1,mark.optInt("chapter")));long absolute=old.trackStart(chapter)+mark.optLong("position");int next=index(found.markers,absolute);mark.put("chapter",next).put("position",Math.max(0,absolute-found.markers.get(next).time));}c.getSharedPreferences("bookmarks",0).edit().putString(key,marks.toString()).apply();}catch(Exception ignored){}}
 static void save(Context c,Book selected,Discovery found){ArrayList<Book> books=Store.load(c);for(Book b:books)if(b.uri.equals(selected.uri)){if(needs(b)){remap(c,b,found);fill(b,found);Store.save(c,books);}selected.chapters.clear();selected.chapters.addAll(b.chapters);selected.chapterIndex=b.chapterIndex;selected.position=b.position;selected.duration=b.duration;selected.chaptersChecked=b.chaptersChecked;return;}}
}
